      end_point1 = osc_1_buffer[end_index];
      end_point2 = end_point1;

      dsp_i = 0;

      dsp_phase_index = ags_fluid_phase_index(dsp_phase);

      root_pitch_hz = exp2(((double) base_key - 48.0) / 12.0) * 440.0;

