      if(ags_abyss_synth_util_sends_receives(abyss_synth_util,
					     abyss_synth_util->noise_1_sends,
					     AGS_ABYSS_SYNTH_SENDS_RING_0_GAIN)){
	ring_0_gain = ((((double *) abyss_synth_util->noise_1_buffer)[i] + 1.0) / 2.0 * 1200.0) + (ring_0_gain);
      }
            
